import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Science User Group Meetup - Nov 2025","description":"","frontmatter":{"title":"Ceph Science User Group Meetup - Nov 2025","date":"2026-06-11T00:00:00.000Z","updated":"2026-06-12T00:00:00.000Z","tags":["Ceph","BlueStore","Erasure Coding","RGW","社区动态"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_Science_User_Group_Meetup_-_Nov_2025.md","filePath":"posts/2026/Ceph_Science_User_Group_Meetup_-_Nov_2025.md","lastUpdated":null}'),l={name:"posts/2026/Ceph_Science_User_Group_Meetup_-_Nov_2025.md"};function i(s,e,n,u,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ceph-science-user-group-meetup-nov-2025-会议纪要" tabindex="-1">Ceph Science User Group Meetup - Nov 2025 会议纪要 <a class="header-anchor" href="#ceph-science-user-group-meetup-nov-2025-会议纪要" aria-label="Permalink to &quot;Ceph Science User Group Meetup - Nov 2025 会议纪要&quot;">​</a></h1><h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次会议为 Ceph 科学用户组（Ceph Science Working Group）2025 年 11 月例会。由于正值 11 月会议旺季（Cephalocon、SuperComputing、KubeCon、AGU 等会议密集），本次参会人数较少，未安排正式 presentation，主要以非正式讨论的形式围绕近期 Cephalocon 见闻、Squid 版本相关 bug、Tentacle 升级计划、CRUSH 平衡问题、RGW 认证方案等主题展开交流。会议内容已录制并将发布至 Ceph YouTube 官方频道。</p><h2 id="一、cephalocon-与-ceph-days-见闻" tabindex="-1">一、Cephalocon 与 Ceph Days 见闻 <a class="header-anchor" href="#一、cephalocon-与-ceph-days-见闻" aria-label="Permalink to &quot;一、Cephalocon 与 Ceph Days 见闻&quot;">​</a></h2><h3 id="_1-tentacle-版本与-fast-ec-新特性" tabindex="-1">1. Tentacle 版本与 Fast EC 新特性 <a class="header-anchor" href="#_1-tentacle-版本与-fast-ec-新特性" aria-label="Permalink to &quot;1. Tentacle 版本与 Fast EC 新特性&quot;">​</a></h3><p>会议中多位与会者表达了对 Tentacle 版本中即将推出的 <strong>Fast EC（Fast Erasure Coding）</strong> 特性的高度期待。该特性的核心改进点：</p><ul><li><strong>去除 padding 开销</strong>：传统 EC 实现对小对象会进行 padding 填充，造成显著的空间浪费。Fast EC 改为按实际数据需要的 k segment 数量进行存储。</li><li><strong>支持大 stripe width</strong>：可以配置非常大的 stripe width，但仅使用容纳数据所需的 k segment，从而在大 stripe width 场景下获得读写性能的&quot;巨大提升&quot;（gigantic boost）。</li><li><strong>支持 partial reads</strong>：可以对 stripe 进行部分读取，进一步提升读性能。</li><li><strong>小对象空间节省显著</strong>。</li><li><strong>可按工作负载与对象大小配置不同 stripe widths</strong>。</li></ul><p>注意事项：</p><ul><li>Fast EC 仍处于早期阶段，需要与 codebase 中其他模块（如 defragmentation 相关逻辑）做更多协调，避免引入新问题。</li><li>Fast EC 将以 flag 的形式启用，原有 EC 代码会与之共存，新旧代码可并行使用。</li><li>启用 Fast EC 后，<strong>老对象不会自动受益</strong>，仅对启用之后新写入和重新写入的对象生效。是否可通过 reshard bucket 之类的方式触发重写，目前尚不明确。</li></ul><h3 id="_2-多步-crush-rule-multi-step-crush-rule" tabindex="-1">2. 多步 CRUSH Rule（Multi-step CRUSH Rule） <a class="header-anchor" href="#_2-多步-crush-rule-multi-step-crush-rule" aria-label="Permalink to &quot;2. 多步 CRUSH Rule（Multi-step CRUSH Rule）&quot;">​</a></h3><p>新的 multi-step CRUSH rule 允许在 failure domain 小于 stripe width 时，CRUSH 进行多次尝试以放置 PG，而不是直接失败。</p><p>应用示例：4 个 rack，6+2 EC 配置不可行，但 5+3 stripe 是可行的——即使单个 rack 内同时存在 2 个 segment，仍可承受丢失一个 rack。stripe width 不再与 OSD 的 failure domain 严格耦合。该机制可与 Fast EC 的大 stripe width 形成良好配合。</p><h3 id="_3-bpf-tracing-工具-canonical-开源" tabindex="-1">3. BPF Tracing 工具（Canonical 开源） <a class="header-anchor" href="#_3-bpf-tracing-工具-canonical-开源" aria-label="Permalink to &quot;3. BPF Tracing 工具（Canonical 开源）&quot;">​</a></h3><p>来自 Canonical 的 BPF talk 介绍了一套开源的 OSD 与 RADOS BPF tracing 工具，可在 BPF 层面对 Ceph 进行细粒度追踪，对排查 OSD 行为异常非常有帮助。</p><h3 id="_4-kso-clyso-关于-adoc-的工具分享" tabindex="-1">4. KSO/Clyso 关于 ADOC 的工具分享 <a class="header-anchor" href="#_4-kso-clyso-关于-adoc-的工具分享" aria-label="Permalink to &quot;4. KSO/Clyso 关于 ADOC 的工具分享&quot;">​</a></h3><p>KSO/Clyso 的工程师分享了 ADOC 中一些未文档化但有价值的内部信息，并提供了相应的命令行可视化工具（talk 名称类似 &quot;gems&quot;），可图形化展示 ADOC 内部数据。</p><h3 id="_5-berlin-ceph-days" tabindex="-1">5. Berlin Ceph Days <a class="header-anchor" href="#_5-berlin-ceph-days" aria-label="Permalink to &quot;5. Berlin Ceph Days&quot;">​</a></h3><p>本次会议中无人参加在 Berlin 举办的 Ceph Days，因此未带来现场反馈。</p><h2 id="二、squid-版本两个重大-bug-讨论" tabindex="-1">二、Squid 版本两个重大 Bug 讨论 <a class="header-anchor" href="#二、squid-版本两个重大-bug-讨论" aria-label="Permalink to &quot;二、Squid 版本两个重大 Bug 讨论&quot;">​</a></h2><p>本次会议的核心技术讨论集中在 Squid（19.2.x）版本中两个严重 bug，提醒社区在升级到 Squid 前慎重评估。</p><h3 id="bug-1-elastic-shared-blobs-引发-osd-崩溃" tabindex="-1">Bug 1：Elastic Shared Blobs 引发 OSD 崩溃 <a class="header-anchor" href="#bug-1-elastic-shared-blobs-引发-osd-崩溃" aria-label="Permalink to &quot;Bug 1：Elastic Shared Blobs 引发 OSD 崩溃&quot;">​</a></h3><p><strong>触发条件（可能多个条件叠加）：</strong></p><ul><li>启用了 <strong>Elastic Shared Blobs</strong> 功能（Squid 中默认启用，BlueStore 相关新特性）</li><li>在 Squid 上创建新的 OSD（全新部署，或从 Reef 升级后新增/替换磁盘）</li><li>使用 <strong>Erasure Coding</strong>（Replication 暂未观察到大规模影响，但仍存疑）</li></ul><p><strong>实际影响：</strong></p><ul><li>多位用户反馈触发 OSD crash。</li><li>一位与会者在小型 K4+M2 集群中，几小时内连续坏掉 3 个 OSD，几乎丢失一个 PG，最后通过 <code>ceph-objectstore-tool</code> 导出 PG 与对象数据才得以保住数据。这是其使用 Ceph 以来最接近数据丢失的一次。</li><li>影响范围尚不完全清楚：bug tracker 中有报告显示，问题可能&quot;扩散&quot;到原本在 Reef 上创建的 OSD，并非严格只影响 Squid 新建的 OSD。</li></ul><p><strong>当前缓解方案：</strong></p><ul><li>升级 Squid 后<strong>立即禁用</strong> Elastic Shared Blobs（注意：完整名称是 elastic shared blobs，并非&quot;elastic blob store&quot;）。</li><li>已用 Squid 创建的 OSD 需要逐个重建（rm 然后重新创建）。建议按 failure domain 批次操作，并结合 OSD spec 让 Cephadm/orchestrator 自动调度。</li><li>推荐对存量 OSD 执行 <code>fsck</code>（Dan 在 bug tracker 上提供了相关命令），确认数据一致性。</li></ul><p><strong>修复进度：</strong></p><ul><li>修复 PR 已合并到 main 分支。</li><li>截至会议时尚未 backport 到任何 release 版本。</li></ul><h3 id="bug-2-ceph-volume-activate-极端缓慢" tabindex="-1">Bug 2：ceph-volume activate 极端缓慢 <a class="header-anchor" href="#bug-2-ceph-volume-activate-极端缓慢" aria-label="Permalink to &quot;Bug 2：ceph-volume activate 极端缓慢&quot;">​</a></h3><p><strong>现象：</strong></p><ul><li>Reef 上：15 块盘的节点退出 maintenance（OSD container 全部启动）耗时约 <strong>10 秒</strong>。</li><li>Squid 上：22 块盘的节点退出 maintenance 耗时约 <strong>2 分钟</strong>。</li><li><code>top</code> 中可见数百个 <code>lsblk</code> 等子进程持续执行。</li><li>60 块盘的节点：单 OSD 启动时间最长可达 12 分钟，整体 activate 时长超过 5 分钟，systemd 默认 timeout 会被触发。</li></ul><p><strong>影响：</strong></p><ul><li>节点 maintenance/重启后 OSD 长时间无法上线。</li><li>部署新节点（即便仅有 12 块盘）时，orchestrator 通常成功部署 ~8 个 OSD 后开始超时失败。</li><li>60+ 盘的高密度节点难以正常部署。</li></ul><p><strong>当前缓解方案：</strong></p><ul><li>修改 systemd 的 timeout，例如调整到 20 分钟，缓解重启场景的失败。</li><li>创建 OSD 的 timeout 在 ceph-volume 内部某处，目前会议中尚无人精确定位到代码位置（与会者公开求助）。</li><li>部分用户使用<strong>自定义镜像 / 重新部署</strong>作为 workaround，但与会者尚未亲自验证。</li><li>bug tracker 上无 PR、无活跃修复进展，新 20.x release 中预计也尚未修复。</li></ul><p><strong>结论：</strong> 拥有大量大盘节点的集群应<strong>推迟升级到 Squid</strong>，等待修复。</p><h2 id="三、升级与版本规划现状" tabindex="-1">三、升级与版本规划现状 <a class="header-anchor" href="#三、升级与版本规划现状" aria-label="Permalink to &quot;三、升级与版本规划现状&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用户</th><th>当前版本</th><th>升级计划</th></tr></thead><tbody><tr><td>用户 A</td><td>18.2.5 / 18.2.4</td><td>计划升到 18.2.7，Tentacle 还很远</td></tr><tr><td>用户 B</td><td>Squid（部分集群）</td><td>由于稳定性问题暂不进 Tentacle</td></tr><tr><td>用户 C（服务商）</td><td>大量客户在 Reef（最新 stable）</td><td>部分客户升 Squid 时遇到上述 bug，整体放慢节奏；同事 P 已为 Ansible collection 添加 Tentacle 支持，将先在 CI 中部署测试，不接触真实数据</td></tr></tbody></table><p>整体共识：<strong>Squid 体验不佳</strong>，建议大客户继续观望或留在 Reef 上；Tentacle 距离生产可用还有较长时间。</p><h2 id="四、crush-平衡性讨论" tabindex="-1">四、CRUSH 平衡性讨论 <a class="header-anchor" href="#四、crush-平衡性讨论" aria-label="Permalink to &quot;四、CRUSH 平衡性讨论&quot;">​</a></h2><p>讨论了在 rack 作为 failure domain 的情况下，单个 host 故障导致 PG 分布严重不均的问题。</p><p><strong>场景：</strong></p><ul><li>5 个 rack，每个 rack 约 4 个 server，整体集群约 20 个 host。</li><li>一个 server 故障后，剩余 OSD 上的 PG 分布出现明显倾斜，部分 OSD 接近 nearfull。</li><li>集群整体使用率 &lt; 80%，但失衡放大了风险。</li></ul><p><strong>与开发者交流后的预期：</strong></p><ul><li>CRUSH 在遇到故障 host 时，应&quot;再试一次（try again）&quot;，统计上仍能保持较平滑的分布。</li><li>即使 OSD <code>out</code>，只要在 CRUSH map 中权重未清零，理论上分布应基本均衡。</li></ul><p><strong>实际经验：</strong></p><ul><li>多位与会者证实：单/双盘故障后，数据明显偏向同 host 内剩余 OSD。</li><li>把权重直接置零会引发<strong>远超故障盘范围的数据迁移</strong>——会触发与故障无关的 PG 重平衡。</li><li>高密度盘节点症状不明显（绝对盘数大），但小集群更容易触发风险，特别是集群水位本就高（如 85%）时会很快暴露。</li></ul><p><strong>后续行动：</strong> 一位与会者表示将做更多测试，若有结果会在下次会议中分享。</p><h2 id="五、rgw-认证方案讨论" tabindex="-1">五、RGW 认证方案讨论 <a class="header-anchor" href="#五、rgw-认证方案讨论" aria-label="Permalink to &quot;五、RGW 认证方案讨论&quot;">​</a></h2><h3 id="_1-rgw-用户管理选型" tabindex="-1">1. RGW 用户管理选型 <a class="header-anchor" href="#_1-rgw-用户管理选型" aria-label="Permalink to &quot;1. RGW 用户管理选型&quot;">​</a></h3><p>提出讨论：<strong>Keystone vs 手工创建用户</strong>。</p><p><strong>与会者使用情况：</strong></p><ul><li>用户多以内部服务为主，规模较小，仅有少量用户，目前都采用<strong>手工创建</strong>。</li><li>Keystone 自身需要单独运维，引入复杂度，在用户量小的情况下并不划算。</li><li>目前未形成&quot;何时该切到 Keystone&quot;的明确指引，欢迎更多大规模用户分享经验。</li></ul><h3 id="_2-openstack-keystone-安全公告-重要" tabindex="-1">2. OpenStack Keystone 安全公告（重要） <a class="header-anchor" href="#_2-openstack-keystone-安全公告-重要" aria-label="Permalink to &quot;2. OpenStack Keystone 安全公告（重要）&quot;">​</a></h3><p>近期 OpenStack 发布的安全公告对<strong>RGW + Keystone 集成</strong>的用户尤其重要：</p><p><strong>漏洞描述：</strong></p><ul><li>Keystone 可生成 S3 credentials 并提供给 RGW 用作 bucket 访问。</li><li>如果使用此凭证生成的 <strong>pre-signed bucket URL</strong> 被泄露给攻击者，攻击者可基于该 URL 重建对应账户的凭证。</li><li>进一步可使用该凭证调用 <strong>OpenStack API</strong>，等同于获得 token 来源 project 的 member 权限——即便初始 token 仅为 read-only / bucket 范围。</li></ul><p><strong>影响评估：</strong></p><ul><li>仅做 RGW 认证：影响相对有限。</li><li>RGW 与完整 OpenStack 集成：可能造成严重影响。</li></ul><p><strong>缓解方案：</strong></p><ul><li>升级到修补版 Keystone，相对容易，<strong>强烈建议立即升级</strong>。</li><li>服务商已为客户全量打补丁。</li></ul><p>详见会议 Pad 中粘贴的 ticket 链接。</p><h2 id="六、其他话题" tabindex="-1">六、其他话题 <a class="header-anchor" href="#六、其他话题" aria-label="Permalink to &quot;六、其他话题&quot;">​</a></h2><h3 id="_1-osd-redeploy-的语义澄清" tabindex="-1">1. OSD redeploy 的语义澄清 <a class="header-anchor" href="#_1-osd-redeploy-的语义澄清" aria-label="Permalink to &quot;1. OSD redeploy 的语义澄清&quot;">​</a></h3><p><code>ceph orch redeploy</code> 仅重新部署 <strong>container</strong>，不会改变磁盘上数据。要&quot;重建 OSD&quot;必须执行 <strong>rm 然后重建</strong>，且需按 failure domain 逐节点/逐域操作（取决于 CRUSH rule）。配合 OSD specs，Cephadm 可较高效地完成大规模重建。</p><h3 id="_2-supercomputing-st-louis" tabindex="-1">2. SuperComputing（St. Louis） <a class="header-anchor" href="#_2-supercomputing-st-louis" aria-label="Permalink to &quot;2. SuperComputing（St. Louis）&quot;">​</a></h3><p>一名与会者询问是否有人参加 St. Louis 的 SuperComputing 会议并见到 Ceph 相关 presentation。Tom 是相关参会者，但本次未到场，未取得反馈。</p><h3 id="_3-单-bucket-半公开外部访问" tabindex="-1">3. 单 bucket 半公开外部访问 <a class="header-anchor" href="#_3-单-bucket-半公开外部访问" aria-label="Permalink to &quot;3. 单 bucket 半公开外部访问&quot;">​</a></h3><p>一位与会者分享需求：希望仅对外暴露 RGW 的<strong>单个 bucket</strong> 的只读访问，但又不希望把整个 RGW endpoint 直接放到公网上。其使用场景类似过去用 FTP 站点对外公开发布数据集，也用于支撑 GitHub workflows 从内网下载数据。</p><p><strong>正在评估的方案：</strong></p><ul><li>使用 <strong>NGINX S3 Gateway</strong> 项目（官方 Docker 镜像），将其作为前置代理，对外仅暴露指定 bucket 的只读 HTTP 接口。</li></ul><p><strong>社区反馈：</strong> 目前其他与会者未有相关使用经验。提议者将在下次会议反馈测试结果。</p><h2 id="七、决定事项与后续行动" tabindex="-1">七、决定事项与后续行动 <a class="header-anchor" href="#七、决定事项与后续行动" aria-label="Permalink to &quot;七、决定事项与后续行动&quot;">​</a></h2><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ol><li>短期内<strong>不建议大规模生产环境升级 Squid</strong>，特别是高密度盘节点和重度使用 EC 的集群。</li><li>已升级到 Squid 的用户应<strong>立即禁用 elastic shared blobs</strong>，并在维护窗口内择机重建受影响的 OSD。</li><li>完成 RGW + Keystone 集成的环境应<strong>优先升级 Keystone</strong>修补版，规避 pre-signed URL 安全漏洞。</li></ol><h3 id="后续行动-action-items" tabindex="-1">后续行动（Action Items） <a class="header-anchor" href="#后续行动-action-items" aria-label="Permalink to &quot;后续行动（Action Items）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>行动项</th><th>负责人</th><th>状态</th></tr></thead><tbody><tr><td>在 Pad 中补充 elastic shared blobs bug、ceph-volume 慢 bug、Cephalocon 关键 talk 链接</td><td>与会多人</td><td>已开始</td></tr><tr><td>调研 ceph-volume 中 OSD 创建相关 timeout 在代码中的位置</td><td>求助中</td><td>待社区回应</td></tr><tr><td>进一步测试 host 故障下 CRUSH 分布失衡问题，下次会议汇报</td><td>提议者</td><td>进行中</td></tr><tr><td>测试 NGINX S3 Gateway 单 bucket 公网只读暴露方案，下次会议反馈</td><td>Kevin</td><td>进行中</td></tr><tr><td>Tentacle 加入 Ansible collection，CI 部署测试（不接触真实数据）</td><td>服务商团队（P）</td><td>进行中</td></tr></tbody></table><h3 id="下次会议时间" tabindex="-1">下次会议时间 <a class="header-anchor" href="#下次会议时间" aria-label="Permalink to &quot;下次会议时间&quot;">​</a></h3><p>由于年底假期密集，下一次会议预定于<strong>2026 年 1 月 27 日</strong>。会议主持祝大家假期愉快。</p>',80)])])}const g=t(l,[["render",i]]);export{p as __pageData,g as default};
